package com.akintel.familyshield;
import android.Manifest; import android.app.*; import android.content.Intent; import android.content.pm.PackageManager; import android.location.*; import android.os.*;
public class LocationShareService extends Service {
 private static final String CHANNEL="family_shield_location"; private LocationManager manager;
 private final LocationListener listener=location->{getSharedPreferences("family_shield_local",MODE_PRIVATE).edit().putString("last_lat",Double.toString(location.getLatitude())).putString("last_lon",Double.toString(location.getLongitude())).putLong("last_location_time",location.getTime()).apply();};
 public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL,"Family Shield location sharing",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}Notification n=new Notification.Builder(this,CHANNEL).setContentTitle("AK INTEL location sharing is active").setContentText("Visible location collection is running on this device. Stop it in Family Shield.").setSmallIcon(android.R.drawable.ic_menu_mylocation).setOngoing(true).build();if(Build.VERSION.SDK_INT>=29)startForeground(41,n,android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION);else startForeground(41,n);if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){stopSelf();return;}manager=(LocationManager)getSystemService(LOCATION_SERVICE);try{manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,60000L,25f,listener,Looper.getMainLooper());Location l=manager.getLastKnownLocation(LocationManager.GPS_PROVIDER);if(l!=null)listener.onLocationChanged(l);}catch(SecurityException e){stopSelf();}}
 public int onStartCommand(Intent i,int flags,int id){return START_NOT_STICKY;} public void onDestroy(){if(manager!=null)try{manager.removeUpdates(listener);}catch(Exception ignored){}super.onDestroy();} public IBinder onBind(Intent i){return null;}
}